import{_ as l,a0 as a,w as r,s as u,ao as o,I as p,x as t,a1 as i,A as n}from"./chunks/framework.C16IyNjs.js";import"./chunks/theme.CClUzVyq.js";const k=JSON.parse('{"title":"深度操作系統成為首個支持人臉解鎖的 Linux 發行版 | LCTT x X-CMD","titleTemplate":false,"description":"深度操作系統成為首個支持人臉解鎖的 Linux 發行版 | LCTT (202204) | X-CMD","frontmatter":{"pageClass":"x-lctt","head":[["meta",{"name":"og:title","content":"深度操作系統成為首個支持人臉解鎖的 Linux 發行版 | LCTT x X-CMD"}],["meta",{"name":"og:description","content":"深度操作系統成為首個支持人臉解鎖的 Linux 發行版 | LCTT (202204) | X-CMD"}]]},"headers":[],"params":{"isLCTT":true,"post":"202204/20220401 Deepin OS Becomes the First Linux Distro to Offer Face Unlock","title":"深度操作系統成為首個支持人臉解鎖的 Linux 發行版","tag":"202204","desc":""},"relativePath":"202204/20220401 Deepin OS Becomes the First Linux Distro to Offer Face Unlock.md","filePath":"[post].md"}'),d={name:"202204/20220401 Deepin OS Becomes the First Linux Distro to Offer Face Unlock.md"};function m(f,e,x,w,h,T){const s=a("Link");return r(),u("div",null,[e[21]||(e[21]=o('<h1 id="深度操作系統成為首個支持人臉解鎖的-linux-發行版" tabindex="-1">深度操作系統成為首個支持人臉解鎖的 Linux 發行版 <a class="header-anchor" href="#深度操作系統成為首個支持人臉解鎖的-linux-發行版" aria-label="Permalink to “深度操作系統成為首個支持人臉解鎖的 Linux 發行版”">​</a></h1><blockquote><p>在提供現代桌面體驗方面，深度佔據了領先地位。</p></blockquote><p><img src="https://i0.wp.com/news.itsfoss.com/wp-content/uploads/2022/04/deepin-20-5-release.png?w=1200&amp;ssl=1" alt=""></p><p>在深度問世時，人們都為它純粹的漂亮界面而驚歎。</p><p>隨着時間的推移，開發人員越來越有經驗，他們把重點轉移到了系統設計和功能上，力求在這些方面和其他的商業操作系統看齊，我指的是 Windows 和 macOS。深度是首個支持安卓應用和雲同步等功能的發行版。</p><p>相信我，這是一件好事情。</p><p>Linux 發行版以各種桌面環境的形式向大眾提供。深度看起來很主流，可以吸引年輕羣體。</p><p>中國的深度開發團隊的也有相同目標，因此深度發佈了 20.5 版本，該版本主要亮點是面部識別。</p><h3 id="深度操作系統-20-5-的新功能" tabindex="-1">深度操作系統 20.5 的新功能 <a class="header-anchor" href="#深度操作系統-20-5-的新功能" aria-label="Permalink to “深度操作系統 20.5 的新功能”">​</a></h3><p>新版本根據用户的反饋增加了幾個功能。穩定的內核版本現在已經升級到 5.15.24，並修復幾個錯誤，以加強系統安全性。</p><p>讓我們來看看這個版本還有哪些新功能吧。</p><h4 id="linux-上有了面部解鎖" tabindex="-1">Linux 上有了面部解鎖 <a class="header-anchor" href="#linux-上有了面部解鎖" aria-label="Permalink to “Linux 上有了面部解鎖”">​</a></h4><p><img src="https://i0.wp.com/news.itsfoss.com/wp-content/uploads/2022/04/face-unlock-deepin.jpg?w=900&amp;ssl=1" alt=""></p>',13)),p("p",null,[e[1]||(e[1]=t("是的，我知道 Linux 上早就有面部解鎖的相關消息了。畢竟，我曾經寫過一篇關於 ",-1)),i(s,{href:"https://itsfoss.com/face-unlock-ubuntu/"},{default:n(()=>[...e[0]||(e[0]=[t("在 Linux 發行版中使用類似 Howdy 的軟件來支持面部解鎖功能",-1)])]),_:1}),e[2]||(e[2]=t(" 的詳細指南。",-1))]),e[22]||(e[22]=o('<p>然而，那些軟件更多的是一種個性化定製，是為那些有經驗的、愛折騰的用户準備的。</p><p>深度現在提供基於人臉的生物識別認證方法。它可以在有內置攝像頭的筆記本電腦上工作。</p><p>你需要先在控制中心錄入人臉信息，此後，你就可以用你的人臉 ID 登錄系統。</p><h4 id="用户可在應用商店中反饋" tabindex="-1">用户可在應用商店中反饋 <a class="header-anchor" href="#用户可在應用商店中反饋" aria-label="Permalink to “用户可在應用商店中反饋”">​</a></h4><p>你現在可以直接在應用商店中提交對某個應用的反饋。</p><p><img src="https://i0.wp.com/news.itsfoss.com/wp-content/uploads/2022/04/app-store-feedback-deepin.webp?resize=1568%2C980&amp;ssl=1" alt=""></p><p>這還不算完。當你有應用程序的安裝和更新問題時，你可以在應用程序中直接向官方支持提交問題，並獲得解決方案（如果開發者提供了的話）。</p><h4 id="改進的郵件應用" tabindex="-1">改進的郵件應用 <a class="header-anchor" href="#改進的郵件應用" aria-label="Permalink to “改進的郵件應用”">​</a></h4><p><img src="https://i0.wp.com/news.itsfoss.com/wp-content/uploads/2022/04/deepin-mail-app.webp?w=900&amp;ssl=1" alt=""></p><p>深度郵件應用現在支持了自定義文件夾管理。它還可以在網絡重新連接後自動接收郵件。郵件應用的框架和插件已經替換成了當下流行的 Vue + TinyMCE。</p><p>現在，你可以通過點擊系統通知直接跳轉到到新郵件。為提高工作效率，你可以置頂常用郵件與合併郵件。你也可以預覽郵件附件。</p><h4 id="可以-釘住-的屏幕截圖" tabindex="-1">可以“釘住”的屏幕截圖 <a class="header-anchor" href="#可以-釘住-的屏幕截圖" aria-label="Permalink to “可以“釘住”的屏幕截圖”">​</a></h4><p><img src="https://i0.wp.com/news.itsfoss.com/wp-content/uploads/2022/04/pinned-screenshots-deepin.webp?w=900&amp;ssl=1" alt=""></p><p>你現在可以使用內置的屏幕截圖工具來“釘住”截圖。這樣一來，捕獲的屏幕截圖就會固定在其他應用程序窗口的頂部。從而，你可以同時使用其他應用程序，以提高你的工作效率。另外，置頂的屏幕截圖是可以移動的。</p><h4 id="其他變化" tabindex="-1">其他變化 <a class="header-anchor" href="#其他變化" aria-label="Permalink to “其他變化”">​</a></h4><p>下面是 Deepin 20.5 新版本中的一些其他變化：</p><ul><li>Linux 穩定內核更新到了 5.15.24</li><li>可以為一個有線網絡適配器設置多個 IP</li><li>優化了無線網絡的密碼認證交互</li><li>系統搜索現在可以使用文件類型和擴展名作為關鍵詞</li><li>設備管理器允許你禁用或啓用設備</li><li>瀏覽 docx 文件的文檔查看器得到了性能優化</li></ul>',17)),p("p",null,[e[4]||(e[4]=t("還有許多我沒有提到的小功能和改進。你可以在 ",-1)),i(s,{href:"https://www.deepin.org/en/2022/03/31/deepin-20-5/"},{default:n(()=>[...e[3]||(e[3]=[t("版本發佈説明",-1)])]),_:1}),e[5]||(e[5]=t(" 中瞭解這些內容。",-1))]),e[23]||(e[23]=p("hr",null,null,-1)),p("p",null,[e[7]||(e[7]=t("via: ",-1)),i(s,{href:"https://news.itsfoss.com/deepin-os-20-5-release/"},{default:n(()=>[...e[6]||(e[6]=[t("https://news.itsfoss.com/deepin-os-20-5-release/",-1)])]),_:1})]),p("p",null,[e[12]||(e[12]=t("作者：",-1)),i(s,{href:"https://news.itsfoss.com/author/root/"},{default:n(()=>[...e[8]||(e[8]=[t("Abhishek",-1)])]),_:1}),e[13]||(e[13]=t(" 選題：",-1)),i(s,{href:"https://github.com/lujun9972"},{default:n(()=>[...e[9]||(e[9]=[t("lujun9972",-1)])]),_:1}),e[14]||(e[14]=t(" 譯者：",-1)),i(s,{href:"https://github.com/lkxed"},{default:n(()=>[...e[10]||(e[10]=[t("lkxed",-1)])]),_:1}),e[15]||(e[15]=t(" 校對：",-1)),i(s,{href:"https://github.com/wxy"},{default:n(()=>[...e[11]||(e[11]=[t("wxy",-1)])]),_:1})]),p("p",null,[e[18]||(e[18]=t("本文由 ",-1)),i(s,{href:"https://github.com/LCTT/TranslateProject"},{default:n(()=>[...e[16]||(e[16]=[t("LCTT",-1)])]),_:1}),e[19]||(e[19]=t(" 原創編譯，",-1)),i(s,{href:"https://linux.cn/"},{default:n(()=>[...e[17]||(e[17]=[t("Linux中國",-1)])]),_:1}),e[20]||(e[20]=t(" 榮譽推出",-1))])])}const C=l(d,[["render",m]]);export{k as __pageData,C as default};
